sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    if (gs.nil(current.state)) {
        current.state = 'draft';
    }
    if (gs.nil(current.object_type) && !gs.nil(current.object_json)) {
        try {
            var parsed = JSON.parse(current.object_json);
            current.object_type = parsed.type || 'action';
            current.object_id   = parsed.id   || '';
            current.object_name = parsed.name || '';
        } catch (e) {
            gs.warn('MoveworksObject BR: could not parse object_json - ' + e.message);
        }
    }
})(current, previous);
